<?php
require_once __DIR__.'/attachment_common.php';
try{$uid=att_user();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM project_attachments WHERE id=?');$q->execute([$id]);$row=$q->fetch();if(!$row||$row['storage_type']!=='upload')throw new Exception('Datei nicht gefunden.');att_access($pdo,$row['project_id'],$uid);$path=att_dir($row['project_id']).'/'.basename($row['stored_filename']);if(!is_file($path))throw new Exception('Datei fehlt im Speicher.');header('Content-Type: '.($row['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.str_replace('"','',basename($row['original_filename'])).'"');readfile($path);exit;}catch(Throwable $e){http_response_code(404);header('Content-Type:text/plain;charset=utf-8');echo $e->getMessage();}
